INSERT INTO questions (id, content, difficulty, sub_category_id) VALUES
  ('b0000000-0000-0000-0005-000000000000', 'React란 무엇이며 주로 어떤 문제를 해결하기 위해 등장했나요?', 'EASY', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000001', 'JSX란 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000002', 'Virtual DOM은 무엇이며 어떻게 동작하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000003', '클래스형 컴포넌트와 함수형 컴포넌트의 차이는 무엇인가요?', 'EASY', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000004', '상태(State)와 속성(Props)의 차이는?', 'EASY', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000005', '리액트의 생명주기(Lifecycle) 메서드를 설명해 주세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000006', 'Hook이란 무엇이고, useState와 useEffect 훅의 사용법은?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000007', '리액트에서 조건부 렌더링은 어떻게 하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000008', 'React에서 리스트(list)를 렌더링할 때 key를 왜 사용하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000009', 'React의 합성(Composition) vs 상속(Inheritance)에 대해 설명해주세요.', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-00000000000a', '상태 관리(State Management)를 위해 어떤 도구를 사용해봤나요? (예: Redux)', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-00000000000b', 'Context API는 무엇이며 언제 사용하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-00000000000c', 'React.memo는 어떤 기능을 하나요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-00000000000d', 'React의 최적화 기법에는 어떤 것들이 있나요? (예: useMemo, useCallback)', 'HARD', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-00000000000e', '서버 사이드 렌더링(SSR)을 React에서 구현해본 경험이 있나요?', 'HARD', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-00000000000f', '리액트에서 비동기 작업을 처리하는 방법은 무엇이 있나요? (예: axios, fetch)', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000010', '리액트 라우터(React Router)는 무엇이고 어떻게 사용하나요?', 'EASY', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000011', 'React에서 폼(form)을 다룰 때 고려해야 할 사항은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000012', 'SSR과 CSR의 장단점은 무엇인가요?', 'MEDIUM', 'b0000000-0000-0000-0000-000000000005'),
  ('b0000000-0000-0000-0005-000000000013', '리액트에서 에러 바운더리(Error Boundary)는 무엇인가요?', 'HARD', 'b0000000-0000-0000-0000-000000000005');
